\label{prop:relation-to-ddrop}
  For given~$\Gamma,k \in \{0,\ldots,n\}$, suppose that
  $$\max_{x \in X} \left\{ \sum_{i=1}^n x_i \right\} \mathrel{{=}{\mathop:}} \bar n \leq \Gamma + k$$
  holds.
  Then, the~$k$-delete recoverable robust
  problem~\eqref{eq:recoverable-robust-problem} can be solved as the
  robust combinatorial optimization problem
  \begin{equation}
    \label{eq:ddrop}
    \min_{x \in X} \left\{ \sum_{i=1}^n f_ix_i
      + \max_{u \in \mathcal{U}(x)} \left\{\sum_{i=1}^n (\bar{c}_i + \Delta c_i)u_i\right\}\right\}
  \end{equation}
  with the discrete decision-dependent uncertainty set
  \begin{equation*}
    \mathcal{U}(x) = \left\{u \in \{0,1\}^n\defsepx \geq u,\, \sum_{i=1}^n u_i
      \leq \sum_{i=1}^n x_i - k\right\}.
  \end{equation*}

\label{lem:proj-ref}
  For arbitrarily given~$x \in X$, it holds
  \begin{equation}
    \label{eq:proj-ref-alpha}
    \begin{split}
      \beta(x) = 
      \max_{u \in \mathcal{U}_\Gamma,\nu \geq 0}
      \left\{\sum_{i=1}^n \bar{c}_i x_i - k\nu
      + \sum_{i \in N(\nu)} c_{i}(\nu) x_i
      + \sum_{i \in P(\nu)} c_{i}(\nu) x_i u_i\right\}.
    \end{split}
  \end{equation}

