\label{prop:proj-ref}
  Problem~\eqref{eq:recoverable-robust-problem} can be solved as
  \begin{equation*}
    \min_{x \in X} \ f^\top x
    + \max_{\nu \in \mathcal{V}} \left\{\alpha(x,\nu) - k\nu\right\},
  \end{equation*}
  where, for given~$x \in X$ and~$\nu \in \mathcal{V}$, we have
  \begin{equation*}
    \alpha(x,\nu) = \max_{u}\left\{\sum_{i=1}^n \bar{c}_{i}(\nu) x_i
      + \sum_{i=1}^n \Delta c_{i}(\nu) x_i u_i\defsepu \in
      \mathcal{U}_\Gamma\right\}.
  \end{equation*}

\label{thm:proj-ref}
  Problem~\eqref{eq:recoverable-robust-problem} can be solved as the
  mixed-integer linear problem
  \begin{equation}
    \label{eq:proj-ref}
    \begin{split}
      \min_{x,\eta} \quad & f^\top x + \eta
      \\
      \text{s.t.} \quad & \eta \geq \sum_{i=1}^n c^{s}_{i}(\nu) x_i -
                  k\nu,
                  \quad \nu \in \mathcal{V},\, s \in S(\nu),
      \\
                          & x \in X,\, \eta \in \mathbb{R}_{\geq 0},
    \end{split}
  \end{equation}
  where, for all~$\nu \in \mathcal{V}$, we have
  \begin{equation*}
    S(\nu) \mathrel{{\mathop:}{=}} \left\{s \in \left\{1,2,\ldots, M\right\}\colon
      c^{s}_{i}(\nu) \mathrel{{\mathop:}{=}} \bar{c}_{i}(\nu) +
      \Delta c_{i}(\nu) u^s_i,\, i \in N,\, u^s \in \mathcal{U}_\Gamma\right\}.
  \end{equation*}

\label{prop:compact-formulation}
  Problem~\eqref{eq:recoverable-robust-problem} is equivalent to
  \begin{subequations}
    \label{eq:compact-ref-aux}
    \begin{align}
      \min_{x,\eta} \quad & f^\top x + \eta
      \\
      \text{s.t.} \quad & \eta
                  \geq \min_{\ell \in \mathcal{L}} \left\{\kappa_\ell(\nu)
                  + \sum_{i=1}^n \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)
                  x_{\sigma_\nu(i)}\right\},
                  \quad \nu \in \mathcal{V},
                  \label{eq:compact-form-constr}
      \\
                          & x \in X,\, \eta \in \mathbb{R}_{\geq 0}.
    \end{align}
  \end{subequations}

\label{thm:compact-formulation}
  Problem~\eqref{eq:recoverable-robust-problem} can be solved as the
  mixed-integer linear problem
  \begin{subequations}
    \label{eq:compact-ref}
    \begin{align}
      \min_{x,\eta,y} \quad & f^\top x + \eta
      \\
      \text{s.t.} \quad & \eta
                  \geq \kappa_\ell(\nu)
                  + \sum_{i=1}^n \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)
                  x_{\sigma_\nu(i)} - M(\nu)(1 - y^\nu_\ell),
                  \quad \ell \in \mathcal{L},\, \nu \in \mathcal{V},
      \\
                            & \sum_{\ell \in \mathcal{L}} y^\nu_\ell
                              = 1,
                              \quad \nu \in \mathcal{V},
                              \label{eq:compact-ref:sos1}
      \\
                            & x \in X,\, \eta \in \mathbb{R}_{\geq 0},\,
                              y^\nu \in \left\{0,1\right\}^{\left\lvert\mathcal{L}\right\rvert},
                              \quad \nu \in \mathcal{V}.
                              \label{eq:compact-ref:vars}
    \end{align}
  \end{subequations}

We show that, for an optimal solution~$(x^*,\eta^*,y^*)$ to
  Problem~\eqref{eq:compact-ref}, the pair~$(x^*,\eta^*)$ is an optimal
  solution to Problem~\eqref{eq:compact-ref-aux}.
  We prove this by contradiction.
  To this end, let~$(x^*,\eta^*,y^*)$ be an optimal solution to
  Problem~\eqref{eq:compact-ref} and suppose that~$(x^*,\eta^*)$ does not
  solve Problem~\eqref{eq:compact-ref-aux}, i.e.\xspace, there
  exists~$(\hat x,\hat \eta)$ feasible for Problem~\eqref{eq:compact-ref-aux}
  with~$f^\top \hat x + \hat \eta < f^\top x^* + \eta^*$.
  For all~$\nu \in \mathcal{V}$, we define
  \begin{equation*}
    \ell^*_\nu \mathrel{{\mathop:}{=}} \operatorname*{arg\,min}_{\ell \in \mathcal{L}}
    \left\{\kappa_\ell(\nu) + \sum_{i=1}^n \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)
      \hat x_{\sigma_\nu(i)}\right\}
    \quad \text{and} \quad
    \hat y^\nu_\ell \mathrel{{\mathop:}{=}}
    \begin{cases}
      1, & \ell = \ell^*_\nu,
      \\
      0, & \ell \in \mathcal{L} \setminus \left\{\ell^*_\nu\right\}.
    \end{cases}
  \end{equation*}
  By construction, $(\hat x,\hat \eta, \hat y)$
  with~$\hat y = (\hat y^\nu)_{\nu \in \mathcal{V}}$
  satisfies~\eqref{eq:compact-ref:sos1} and~\eqref{eq:compact-ref:vars}.
  For all~$\nu \in \mathcal{V}$, we further have
  \begin{align*}
    \hat \eta
    & \geq \min_{\ell \in \mathcal{L}} \left\{\kappa_\ell(\nu)
      + \sum_{i=1}^n \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu) \hat
      x_{\sigma_\nu(i)}\right\}
      = \kappa_{\ell^*_\nu}(\nu)
      + \sum_{i=1}^n \tilde{c}^{\,\ell^*_\nu}_{\sigma_\nu(i)}(\nu) \hat
      x_{\sigma_\nu(i)}
    \\
    & = \kappa_{\ell^*_\nu}(\nu)
      + \sum_{i=1}^n \tilde{c}^{\,\ell^*_\nu}_{\sigma_\nu(i)}(\nu) \hat
      x_{\sigma_\nu(i)} - M(\nu)(1 - y^\nu_{\ell^*_\nu})
  \end{align*}
  and
  \begin{align*}
    \hat \eta


    \geq & \ - k\nu + \Gamma \Delta c_{\sigma_\nu(\ell)}(\nu)
           + \sum_{i=1}^n \max \left\{0,\, \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)\right\}
    \\
         & \ - \max_{\ell' \in \mathcal{L}} \left\{
           \Gamma \Delta c_{\sigma_\nu(k)}(\nu)
           + \sum_{i=1}^n \max \left\{0,\, \tilde{c}^{\,\ell'}_{\sigma_\nu(i)}(\nu)\right\}\right\}
    \\
    = & \ \kappa_\ell(\nu)
        + \sum_{i=1}^n \max \left\{0,\, \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)\right\}
        - M(\nu)
    \\
    \geq & \ \kappa_\ell(\nu)
           + \sum_{i=1}^n \max \left\{0,\,
           \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)\right\} \hat x_{\sigma_\nu(i)}
           - M(\nu)
    \\
    \geq & \ \kappa_\ell(\nu)
           + \sum_{i=1}^n \max \left\{0,\,
           \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)\right\} \hat x_{\sigma_\nu(i)}
           + \sum_{i=1}^n \min \left\{0,\,
           \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu)\right\} \hat x_{\sigma_\nu(i)}
           - M(\nu)
    \\
    = & \ \kappa_\ell(\nu) + \sum_{i=1}^n
        \tilde{c}^{\,\ell}_{\sigma_\nu(i)}(\nu) \hat x_{\sigma_\nu(i)}
        - M(\nu)(1 - \hat{y}^\nu_{\ell})
  \end{align*}
  for all~$\ell \in \mathcal{L} \setminus \left\{\ell^*_\nu\right\}$.
  Hence, the point~$(\hat x,\hat \eta,\hat y)$ is feasible for
  Problem~\eqref{eq:compact-ref}
  and has a better objective function value than~$(x^*,\eta^*,y^*)$.
  This is a contradiction to the optimality of~$(x^*,\eta^*,y^*)$.
  By Proposition~\ref{prop:compact-formulation}, this concludes the proof.

